    showLoading('\u6B63\u5728\u6E05\u7406\u7F13\u5B58...', '\u6E05\u9664\u4E2D\uFF0C\u8BF7\u7A0D\u5019');
    addLog('\u5F00\u59CB\u6E05\u7406\u7F13\u5B58', 'info');

